def intersection(interval1, interval2):
    """Determine if the intersection of two intervals is a prime number in length."""
    start_max = max(interval1[0], interval2[0])
    end_min = min(interval1[1], interval2[1])

    if start_max > end_min:
        return "NO"

    # Calculate the length of the intersection
    intersection_length = end_min - start_max

    # Check if the intersection length is a prime number
    if is_prime(intersection_length):
        return "YES"
    else:
        return "NO"
